/* Orchard — Global Styles */
*, *::before, *::after { margin: 0; padding: 0; box-sizing: border-box; }

:root {
  --color-dark: #1d1d1f;
  --color-bg: #f5f5f7;
  --color-white: #ffffff;
  --color-gray: #6e6e73;
  --color-link: #0066cc;
  --color-link-hover: #004499;
  --font: -apple-system, BlinkMacSystemFont, "SF Pro Display", "SF Pro Text", "Helvetica Neue", Helvetica, Arial, sans-serif;
  --max-width: 1200px;
  --section-pad: 80px 0;
}

html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font); color: var(--color-dark); background: var(--color-white); line-height: 1.5; -webkit-font-smoothing: antialiased; }
a { color: var(--color-link); text-decoration: none; transition: color .2s; }
a:hover { color: var(--color-link-hover); }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ---------- Ribbon Banner ---------- */
.ribbon { background: var(--color-bg); text-align: center; padding: 12px 24px; font-size: 14px; color: var(--color-dark); }
.ribbon a { font-weight: 500; }

/* ---------- Top Navigation ---------- */
.top-nav { background: rgba(255,255,255,.92); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); position: sticky; top: 0; z-index: 100; border-bottom: 1px solid #d2d2d7; }
.top-nav .container { display: flex; align-items: center; justify-content: space-between; height: 48px; }
.nav-logo { font-size: 20px; font-weight: 700; letter-spacing: -.02em; color: var(--color-dark); }
.nav-links { display: flex; gap: 28px; list-style: none; }
.nav-links a { font-size: 13px; color: var(--color-dark); font-weight: 400; opacity: .8; transition: opacity .2s; }
.nav-links a:hover { opacity: 1; }
.nav-links a.active { font-weight: 600; opacity: 1; }
.nav-icons { display: flex; gap: 16px; align-items: center; }
.nav-icons svg { width: 18px; height: 18px; fill: var(--color-dark); opacity: .8; }
.mobile-menu-btn { display: none; }

/* ---------- Section Headers ---------- */
.section-header { margin-bottom: 32px; }
.section-header h2 { font-size: 48px; font-weight: 700; letter-spacing: -.03em; line-height: 1.08; color: var(--color-dark); }
.section-header p { font-size: 21px; color: var(--color-gray); margin-top: 6px; font-weight: 400; }

/* ---------- Carousel ---------- */
.carousel-wrapper { position: relative; }
.carousel-track { display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; -ms-overflow-style: none; scroll-behavior: smooth; padding: 8px 0 16px; }
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track > * { scroll-snap-align: start; flex-shrink: 0; }
.carousel-btn { position: absolute; top: 50%; transform: translateY(-50%); width: 40px; height: 40px; border-radius: 50%; background: rgba(255,255,255,.9); border: 1px solid #d2d2d7; display: flex; align-items: center; justify-content: center; z-index: 5; box-shadow: 0 2px 8px rgba(0,0,0,.1); transition: background .2s, box-shadow .2s; }
.carousel-btn:hover { background: #fff; box-shadow: 0 4px 12px rgba(0,0,0,.15); }
.carousel-btn svg { width: 16px; height: 16px; fill: #1d1d1f; }
.carousel-btn.prev { left: -8px; }
.carousel-btn.next { right: -8px; }
.carousel-btn:disabled { opacity: .3; pointer-events: none; }

/* ---------- Product Cards (Carousels) ---------- */
.product-card { width: 320px; background: var(--color-white); border-radius: 20px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,.06); transition: transform .25s, box-shadow .25s; display: flex; flex-direction: column; }
.product-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,.1); }
.product-card .card-img { height: 200px; display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden; }
.product-card .card-body { padding: 20px 24px 24px; flex: 1; display: flex; flex-direction: column; }
.product-card .badge { display: inline-block; font-size: 11px; font-weight: 600; color: #bf4800; background: #fef0e0; padding: 2px 8px; border-radius: 4px; margin-bottom: 8px; width: fit-content; }
.product-card .card-title { font-size: 22px; font-weight: 700; letter-spacing: -.01em; }
.product-card .card-tagline { font-size: 14px; color: var(--color-gray); margin-top: 4px; }
.product-card .card-price { font-size: 15px; font-weight: 600; margin-top: auto; padding-top: 16px; }
.product-card .card-monthly { font-size: 13px; color: var(--color-gray); margin-top: 2px; }
.product-card .card-note { font-size: 12px; color: var(--color-link); margin-top: 4px; }

/* Card image backgrounds for variety */
.card-img.bg-blue { background: linear-gradient(135deg, #e8f0fe, #c5d9f7); }
.card-img.bg-purple { background: linear-gradient(135deg, #f0e8fe, #d5c5f7); }
.card-img.bg-pink { background: linear-gradient(135deg, #fee8f0, #f7c5d5); }
.card-img.bg-green { background: linear-gradient(135deg, #e8fee8, #c5f7c5); }
.card-img.bg-orange { background: linear-gradient(135deg, #fff3e0, #ffe0b2); }
.card-img.bg-dark { background: linear-gradient(135deg, #2c2c2e, #3a3a3c); }
.card-img.bg-gray { background: linear-gradient(135deg, #e5e5ea, #d1d1d6); }
.card-img.bg-teal { background: linear-gradient(135deg, #e0f7fa, #b2ebf2); }

.card-img .product-icon { font-size: 64px; opacity: .6; }

/* ---------- Hero Sections ---------- */
.hero { text-align: center; padding: 60px 24px 48px; }
.hero h1 { font-size: 56px; font-weight: 700; letter-spacing: -.03em; line-height: 1.05; }
.hero .subtitle { font-size: 24px; color: var(--color-gray); margin-top: 8px; font-weight: 400; }
.hero-ctas { display: flex; gap: 24px; justify-content: center; margin-top: 20px; flex-wrap: wrap; }
.hero-ctas a { font-size: 18px; font-weight: 400; }

/* ---------- Homepage Product Grid ---------- */
.product-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; padding: 0 24px 60px; max-width: 1200px; margin: 0 auto; }
.grid-tile { border-radius: 24px; overflow: hidden; padding: 48px 40px; min-height: 460px; display: flex; flex-direction: column; position: relative; text-align: center; transition: transform .3s; }
.grid-tile:hover { transform: scale(1.005); }
.grid-tile h3 { font-size: 36px; font-weight: 700; letter-spacing: -.02em; line-height: 1.1; }
.grid-tile p { font-size: 18px; color: var(--color-gray); margin-top: 6px; }
.grid-tile .tile-ctas { display: flex; gap: 20px; justify-content: center; margin-top: 16px; }
.grid-tile .tile-ctas a { font-size: 18px; font-weight: 400; }
.grid-tile .tile-visual { flex: 1; display: flex; align-items: center; justify-content: center; margin-top: 24px; }
.grid-tile .tile-icon { font-size: 80px; opacity: .3; }

.tile-dark { background: var(--color-dark); color: #fff; }
.tile-dark p { color: #a1a1a6; }
.tile-dark a { color: #6cb4ff; }
.tile-light { background: var(--color-bg); color: var(--color-dark); }
.tile-blue { background: linear-gradient(180deg, #1b3a5c, #0e1f33); color: #fff; }
.tile-blue p { color: #a1b5cc; }
.tile-blue a { color: #6cb4ff; }
.tile-warm { background: linear-gradient(180deg, #3d2b1f, #1a120d); color: #fff; }
.tile-warm p { color: #c4a98a; }
.tile-warm a { color: #ffb347; }
.tile-purple { background: linear-gradient(180deg, #2d1f5e, #1a1040); color: #fff; }
.tile-purple p { color: #b0a0d4; }
.tile-purple a { color: #b794f6; }
.tile-green { background: linear-gradient(180deg, #e8fce8, #f5f5f7); color: var(--color-dark); }

/* ---------- Entertainment Tabs ---------- */
.entertainment-section { padding: var(--section-pad); background: var(--color-dark); color: #fff; }
.entertainment-section .section-header h2 { color: #fff; }
.entertainment-section .section-header p { color: #a1a1a6; }
.tab-bar { display: flex; gap: 0; margin-bottom: 32px; border-bottom: 1px solid #424245; }
.tab-btn { padding: 12px 28px; font-size: 16px; font-weight: 500; color: #a1a1a6; background: none; border: none; border-bottom: 2px solid transparent; transition: color .2s, border-color .2s; cursor: pointer; }
.tab-btn:hover { color: #f5f5f7; }
.tab-btn.active { color: #fff; border-bottom-color: #fff; }
.tab-content { display: none; }
.tab-content.active { display: flex; gap: 20px; overflow-x: auto; padding-bottom: 8px; scrollbar-width: none; }
.tab-content::-webkit-scrollbar { display: none; }
.ent-card { flex-shrink: 0; width: 260px; border-radius: 16px; overflow: hidden; position: relative; transition: transform .25s; }
.ent-card:hover { transform: translateY(-4px); }
.ent-card .ent-img { height: 160px; display: flex; align-items: center; justify-content: center; }
.ent-card .ent-body { padding: 16px 20px; background: #2c2c2e; }
.ent-card .ent-title { font-size: 16px; font-weight: 600; color: #fff; }
.ent-card .ent-subtitle { font-size: 13px; color: #a1a1a6; margin-top: 4px; }
.ent-card .ent-cta { font-size: 14px; color: #6cb4ff; margin-top: 8px; display: inline-block; }

/* ---------- Product Icon Bar ---------- */
.icon-bar { display: flex; gap: 32px; justify-content: center; padding: 32px 24px; flex-wrap: wrap; }
.icon-bar a { display: flex; flex-direction: column; align-items: center; gap: 8px; color: var(--color-dark); font-size: 12px; font-weight: 500; text-decoration: none; transition: opacity .2s; }
.icon-bar a:hover { opacity: .7; }
.icon-bar .icon-circle { width: 64px; height: 64px; border-radius: 50%; background: var(--color-bg); display: flex; align-items: center; justify-content: center; font-size: 28px; }

/* ---------- Help / Store Difference / Compact Cards ---------- */
.compact-card { width: 240px; text-align: center; padding: 32px 20px; background: var(--color-white); border-radius: 20px; box-shadow: 0 4px 20px rgba(0,0,0,.06); transition: transform .25s; }
.compact-card:hover { transform: translateY(-4px); }
.compact-card .compact-icon { font-size: 40px; margin-bottom: 12px; }
.compact-card h4 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }
.compact-card p { font-size: 13px; color: var(--color-gray); line-height: 1.4; }

/* ---------- Brand Collab ---------- */
.brand-collab { background: linear-gradient(135deg, #1a1a2e, #16213e); color: #fff; border-radius: 24px; padding: 60px 48px; text-align: center; }
.brand-collab h2 { font-size: 40px; font-weight: 700; letter-spacing: -.02em; }
.brand-collab p { color: #a1a1a6; font-size: 18px; margin-top: 8px; }

/* ---------- Savings Cards ---------- */
.savings-card { width: 280px; padding: 32px 24px; background: var(--color-bg); border-radius: 20px; transition: transform .25s; }
.savings-card:hover { transform: translateY(-4px); }
.savings-card .savings-icon { font-size: 36px; margin-bottom: 12px; }
.savings-card h4 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }
.savings-card p { font-size: 13px; color: var(--color-gray); line-height: 1.4; }

/* ---------- Quick Links ---------- */
.quick-links { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; padding: 40px 24px; }
.quick-link-btn { display: inline-flex; align-items: center; gap: 6px; padding: 10px 20px; border-radius: 24px; border: 1px solid #d2d2d7; font-size: 14px; font-weight: 500; color: var(--color-dark); background: var(--color-white); transition: background .2s, border-color .2s; }
.quick-link-btn:hover { background: var(--color-bg); border-color: #b0b0b5; }

/* ---------- Sticky Section Nav (Category Pages) ---------- */
.section-nav { position: sticky; top: 48px; z-index: 90; background: rgba(255,255,255,.92); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); border-bottom: 1px solid #d2d2d7; }
.section-nav .container { display: flex; gap: 0; overflow-x: auto; scrollbar-width: none; }
.section-nav .container::-webkit-scrollbar { display: none; }
.section-nav a { padding: 14px 20px; font-size: 13px; font-weight: 500; color: var(--color-gray); white-space: nowrap; border-bottom: 2px solid transparent; transition: color .2s, border-color .2s; }
.section-nav a:hover { color: var(--color-dark); }
.section-nav a.active { color: var(--color-dark); border-bottom-color: var(--color-dark); }

/* ---------- Section Spacing ---------- */
.page-section { padding: var(--section-pad); }
.page-section.alt-bg { background: var(--color-bg); }

/* ---------- Setup / Support ---------- */
.support-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; }
.support-card { background: var(--color-white); border-radius: 20px; padding: 32px 24px; box-shadow: 0 4px 20px rgba(0,0,0,.06); text-align: center; transition: transform .25s; }
.support-card:hover { transform: translateY(-4px); }
.support-card .support-icon { font-size: 40px; margin-bottom: 12px; }
.support-card h4 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }
.support-card p { font-size: 13px; color: var(--color-gray); }

/* ---------- Footer ---------- */
.site-footer { background: var(--color-bg); padding: 40px 0 24px; border-top: 1px solid #d2d2d7; }
.footer-columns { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 24px; }
.footer-col h5 { font-size: 12px; font-weight: 700; color: var(--color-dark); margin-bottom: 8px; cursor: default; }
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 4px; }
.footer-col a { font-size: 12px; color: var(--color-gray); transition: color .2s; }
.footer-col a:hover { color: var(--color-dark); }
.footer-legal { margin-top: 32px; padding-top: 16px; border-top: 1px solid #d2d2d7; font-size: 11px; color: var(--color-gray); line-height: 1.6; text-align: center; }

/* ---------- Mobile Footer Accordion ---------- */
.footer-toggle { display: none; }

@media (max-width: 767px) {
  .footer-col h5 { cursor: pointer; display: flex; justify-content: space-between; align-items: center; padding: 12px 0; margin-bottom: 0; font-size: 13px; border-bottom: 1px solid #d2d2d7; }
  .footer-col h5::after { content: '+'; font-size: 18px; font-weight: 300; transition: transform .2s; }
  .footer-col h5.open::after { content: '\2212'; }
  .footer-col ul { display: none; padding: 8px 0; }
  .footer-col ul.open { display: block; }
  .footer-columns { grid-template-columns: 1fr; gap: 0; }
}

/* ---------- Responsive ---------- */
@media (max-width: 1024px) {
  .section-header h2 { font-size: 36px; }
  .hero h1 { font-size: 42px; }
  .grid-tile h3 { font-size: 28px; }
  .product-card { width: 280px; }
}

@media (max-width: 767px) {
  .nav-links { display: none; }
  .mobile-menu-btn { display: block; }
  .section-header h2 { font-size: 28px; }
  .section-header p { font-size: 17px; }
  .hero h1 { font-size: 32px; }
  .hero .subtitle { font-size: 18px; }
  .product-grid { grid-template-columns: 1fr; padding: 0 16px 40px; }
  .grid-tile { min-height: 360px; padding: 32px 24px; }
  .product-card { width: 260px; }
  .compact-card { width: 200px; }
  .savings-card { width: 240px; }
  .brand-collab { padding: 40px 24px; margin: 0 16px; }
  .brand-collab h2 { font-size: 28px; }
  .page-section { padding: 48px 0; }
  .carousel-btn { width: 34px; height: 34px; }
  .carousel-btn.prev { left: 4px; }
  .carousel-btn.next { right: 4px; }
  .icon-bar { gap: 20px; }
}

