  --max-width: 1200px;
  --section-pad: 80px 0;
}

html { scroll-behavior: smooth; font-size: 16px; }
body { font-family: var(--font); color: var(--color-dark); background: var(--color-white); line-height: 1.5; -webkit-font-smoothing: antialiased; }
a { color: var(--color-link); text-decoration: none; transition: color .2s; }
a:hover { color: var(--color-link-hover); }
img { max-width: 100%; display: block; }
button { font-family: inherit; cursor: pointer; border: none; background: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ---------- Ribbon Banner ---------- */
.ribbon { background: var(--color-bg); text-align: center; padding: 12px 24px; font-size: 14px; color: var(--color-dark); }
