.top-nav { background: rgba(255,255,255,.92); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); position: sticky; top: 0; z-index: 100; border-bottom: 1px solid #d2d2d7; }
.top-nav .container { display: flex; align-items: center; justify-content: space-between; height: 48px; }
.nav-logo { font-size: 20px; font-weight: 700; letter-spacing: -.02em; color: var(--color-dark); }
.nav-links { display: flex; gap: 28px; list-style: none; }
.nav-links a { font-size: 13px; color: var(--color-dark); font-weight: 400; opacity: .8; transition: opacity .2s; }
.nav-links a:hover { opacity: 1; }
.nav-links a.active { font-weight: 600; opacity: 1; }
.nav-icons { display: flex; gap: 16px; align-items: center; }
.nav-icons svg { width: 18px; height: 18px; fill: var(--color-dark); opacity: .8; }
.mobile-menu-btn { display: none; }

/* ---------- Section Headers ---------- */
.section-header { margin-bottom: 32px; }
.section-header h2 { font-size: 48px; font-weight: 700; letter-spacing: -.03em; line-height: 1.08; color: var(--color-dark); }
.section-header p { font-size: 21px; color: var(--color-gray); margin-top: 6px; font-weight: 400; }

/* ---------- Carousel ---------- */
.carousel-wrapper { position: relative; }
.carousel-track { display: flex; gap: 20px; overflow-x: auto; scroll-snap-type: x mandatory; scrollbar-width: none; -ms-overflow-style: none; scroll-behavior: smooth; padding: 8px 0 16px; }
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track > * { scroll-snap-align: start; flex-shrink: 0; }
.carousel-btn { position: absolute; top: 50%; transform: translateY(-50%); width: 40px; height: 40px; border-radius: 50%; background: rgba(255,255,255,.9); border: 1px solid #d2d2d7; display: flex; align-items: center; justify-content: center; z-index: 5; box-shadow: 0 2px 8px rgba(0,0,0,.1); transition: background .2s, box-shadow .2s; }
.carousel-btn:hover { background: #fff; box-shadow: 0 4px 12px rgba(0,0,0,.15); }
.carousel-btn svg { width: 16px; height: 16px; fill: #1d1d1f; }
.carousel-btn.prev { left: -8px; }
.carousel-btn.next { right: -8px; }
.carousel-btn:disabled { opacity: .3; pointer-events: none; }

/* ---------- Product Cards (Carousels) ---------- */
.product-card { width: 320px; background: var(--color-white); border-radius: 20px; overflow: hidden; box-shadow: 0 4px 20px rgba(0,0,0,.06); transition: transform .25s, box-shadow .25s; display: flex; flex-direction: column; }
.product-card:hover { transform: translateY(-4px); box-shadow: 0 8px 30px rgba(0,0,0,.1); }
.product-card .card-img { height: 200px; display: flex; align-items: center; justify-content: center; position: relative; overflow: hidden; }
.product-card .card-body { padding: 20px 24px 24px; flex: 1; display: flex; flex-direction: column; }
.product-card .badge { display: inline-block; font-size: 11px; font-weight: 600; color: #bf4800; background: #fef0e0; padding: 2px 8px; border-radius: 4px; margin-bottom: 8px; width: fit-content; }
.product-card .card-title { font-size: 22px; font-weight: 700; letter-spacing: -.01em; }
.product-card .card-tagline { font-size: 14px; color: var(--color-gray); margin-top: 4px; }
.product-card .card-price { font-size: 15px; font-weight: 600; margin-top: auto; padding-top: 16px; }
.product-card .card-monthly { font-size: 13px; color: var(--color-gray); margin-top: 2px; }
