.hero { text-align: center; padding: 60px 24px 48px; }
.hero h1 { font-size: 56px; font-weight: 700; letter-spacing: -.03em; line-height: 1.05; }
.hero .subtitle { font-size: 24px; color: var(--color-gray); margin-top: 8px; font-weight: 400; }
.hero-ctas { display: flex; gap: 24px; justify-content: center; margin-top: 20px; flex-wrap: wrap; }
.hero-ctas a { font-size: 18px; font-weight: 400; }

