.compact-card .compact-icon { font-size: 40px; margin-bottom: 12px; }
.compact-card h4 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }
.compact-card p { font-size: 13px; color: var(--color-gray); line-height: 1.4; }

