.card-img.bg-pink { background: linear-gradient(135deg, #fee8f0, #f7c5d5); }
.card-img.bg-green { background: linear-gradient(135deg, #e8fee8, #c5f7c5); }
.card-img.bg-orange { background: linear-gradient(135deg, #fff3e0, #ffe0b2); }
.card-img.bg-dark { background: linear-gradient(135deg, #2c2c2e, #3a3a3c); }
.card-img.bg-gray { background: linear-gradient(135deg, #e5e5ea, #d1d1d6); }
.card-img.bg-teal { background: linear-gradient(135deg, #e0f7fa, #b2ebf2); }

