.product-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; padding: 0 24px 60px; max-width: 1200px; margin: 0 auto; }
.grid-tile { border-radius: 24px; overflow: hidden; padding: 48px 40px; min-height: 460px; display: flex; flex-direction: column; position: relative; text-align: center; transition: transform .3s; }
.grid-tile:hover { transform: scale(1.005); }
.grid-tile h3 { font-size: 36px; font-weight: 700; letter-spacing: -.02em; line-height: 1.1; }
.grid-tile p { font-size: 18px; color: var(--color-gray); margin-top: 6px; }
.grid-tile .tile-ctas { display: flex; gap: 20px; justify-content: center; margin-top: 16px; }
.grid-tile .tile-ctas a { font-size: 18px; font-weight: 400; }
.grid-tile .tile-visual { flex: 1; display: flex; align-items: center; justify-content: center; margin-top: 24px; }
.grid-tile .tile-icon { font-size: 80px; opacity: .3; }

.tile-dark { background: var(--color-dark); color: #fff; }
.tile-dark p { color: #a1a1a6; }
.tile-dark a { color: #6cb4ff; }
.tile-light { background: var(--color-bg); color: var(--color-dark); }
.tile-blue { background: linear-gradient(180deg, #1b3a5c, #0e1f33); color: #fff; }
.tile-blue p { color: #a1b5cc; }
.tile-blue a { color: #6cb4ff; }
.tile-warm { background: linear-gradient(180deg, #3d2b1f, #1a120d); color: #fff; }
.tile-warm p { color: #c4a98a; }
.tile-warm a { color: #ffb347; }
.tile-purple { background: linear-gradient(180deg, #2d1f5e, #1a1040); color: #fff; }
.tile-purple p { color: #b0a0d4; }
.tile-purple a { color: #b794f6; }
.tile-green { background: linear-gradient(180deg, #e8fce8, #f5f5f7); color: var(--color-dark); }

