.entertainment-section { padding: var(--section-pad); background: var(--color-dark); color: #fff; }
.entertainment-section .section-header h2 { color: #fff; }
.entertainment-section .section-header p { color: #a1a1a6; }
.tab-bar { display: flex; gap: 0; margin-bottom: 32px; border-bottom: 1px solid #424245; }
.tab-btn { padding: 12px 28px; font-size: 16px; font-weight: 500; color: #a1a1a6; background: none; border: none; border-bottom: 2px solid transparent; transition: color .2s, border-color .2s; cursor: pointer; }
.tab-btn:hover { color: #f5f5f7; }
.tab-btn.active { color: #fff; border-bottom-color: #fff; }
.tab-content { display: none; }
.tab-content.active { display: flex; gap: 20px; overflow-x: auto; padding-bottom: 8px; scrollbar-width: none; }
.tab-content::-webkit-scrollbar { display: none; }
.ent-card { flex-shrink: 0; width: 260px; border-radius: 16px; overflow: hidden; position: relative; transition: transform .25s; }
.ent-card:hover { transform: translateY(-4px); }
.ent-card .ent-img { height: 160px; display: flex; align-items: center; justify-content: center; }
.ent-card .ent-body { padding: 16px 20px; background: #2c2c2e; }
.ent-card .ent-title { font-size: 16px; font-weight: 600; color: #fff; }
.ent-card .ent-subtitle { font-size: 13px; color: #a1a1a6; margin-top: 4px; }
.ent-card .ent-cta { font-size: 14px; color: #6cb4ff; margin-top: 8px; display: inline-block; }

/* ---------- Product Icon Bar ---------- */
.icon-bar { display: flex; gap: 32px; justify-content: center; padding: 32px 24px; flex-wrap: wrap; }
.icon-bar a { display: flex; flex-direction: column; align-items: center; gap: 8px; color: var(--color-dark); font-size: 12px; font-weight: 500; text-decoration: none; transition: opacity .2s; }
.icon-bar a:hover { opacity: .7; }
.icon-bar .icon-circle { width: 64px; height: 64px; border-radius: 50%; background: var(--color-bg); display: flex; align-items: center; justify-content: center; font-size: 28px; }

/* ---------- Help / Store Difference / Compact Cards ---------- */
.compact-card { width: 240px; text-align: center; padding: 32px 20px; background: var(--color-white); border-radius: 20px; box-shadow: 0 4px 20px rgba(0,0,0,.06); transition: transform .25s; }
.compact-card:hover { transform: translateY(-4px); }
.compact-card .compact-icon { font-size: 40px; margin-bottom: 12px; }
.compact-card h4 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }
.compact-card p { font-size: 13px; color: var(--color-gray); line-height: 1.4; }

/* ---------- Brand Collab ---------- */
.brand-collab { background: linear-gradient(135deg, #1a1a2e, #16213e); color: #fff; border-radius: 24px; padding: 60px 48px; text-align: center; }
.brand-collab h2 { font-size: 40px; font-weight: 700; letter-spacing: -.02em; }
.brand-collab p { color: #a1a1a6; font-size: 18px; margin-top: 8px; }

/* ---------- Savings Cards ---------- */
.savings-card { width: 280px; padding: 32px 24px; background: var(--color-bg); border-radius: 20px; transition: transform .25s; }
.savings-card:hover { transform: translateY(-4px); }
.savings-card .savings-icon { font-size: 36px; margin-bottom: 12px; }
.savings-card h4 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }
.savings-card p { font-size: 13px; color: var(--color-gray); line-height: 1.4; }

/* ---------- Quick Links ---------- */
.quick-links { display: flex; gap: 12px; flex-wrap: wrap; justify-content: center; padding: 40px 24px; }
.quick-link-btn { display: inline-flex; align-items: center; gap: 6px; padding: 10px 20px; border-radius: 24px; border: 1px solid #d2d2d7; font-size: 14px; font-weight: 500; color: var(--color-dark); background: var(--color-white); transition: background .2s, border-color .2s; }
.quick-link-btn:hover { background: var(--color-bg); border-color: #b0b0b5; }

/* ---------- Sticky Section Nav (Category Pages) ---------- */
.section-nav { position: sticky; top: 48px; z-index: 90; background: rgba(255,255,255,.92); backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px); border-bottom: 1px solid #d2d2d7; }
.section-nav .container { display: flex; gap: 0; overflow-x: auto; scrollbar-width: none; }
.section-nav .container::-webkit-scrollbar { display: none; }
.section-nav a { padding: 14px 20px; font-size: 13px; font-weight: 500; color: var(--color-gray); white-space: nowrap; border-bottom: 2px solid transparent; transition: color .2s, border-color .2s; }
.section-nav a:hover { color: var(--color-dark); }
.section-nav a.active { color: var(--color-dark); border-bottom-color: var(--color-dark); }

/* ---------- Section Spacing ---------- */
.page-section { padding: var(--section-pad); }
.page-section.alt-bg { background: var(--color-bg); }

/* ---------- Setup / Support ---------- */
.support-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: 20px; }
.support-card { background: var(--color-white); border-radius: 20px; padding: 32px 24px; box-shadow: 0 4px 20px rgba(0,0,0,.06); text-align: center; transition: transform .25s; }
.support-card:hover { transform: translateY(-4px); }
.support-card .support-icon { font-size: 40px; margin-bottom: 12px; }
.support-card h4 { font-size: 16px; font-weight: 700; margin-bottom: 6px; }
.support-card p { font-size: 13px; color: var(--color-gray); }

/* ---------- Footer ---------- */
.site-footer { background: var(--color-bg); padding: 40px 0 24px; border-top: 1px solid #d2d2d7; }
.footer-columns { display: grid; grid-template-columns: repeat(auto-fit, minmax(160px, 1fr)); gap: 24px; }
.footer-col h5 { font-size: 12px; font-weight: 700; color: var(--color-dark); margin-bottom: 8px; cursor: default; }
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 4px; }
.footer-col a { font-size: 12px; color: var(--color-gray); transition: color .2s; }
.footer-col a:hover { color: var(--color-dark); }
.footer-legal { margin-top: 32px; padding-top: 16px; border-top: 1px solid #d2d2d7; font-size: 11px; color: var(--color-gray); line-height: 1.6; text-align: center; }

/* ---------- Mobile Footer Accordion ---------- */
.footer-toggle { display: none; }

@media (max-width: 767px) {
