  .mobile-menu-btn { display: block; }
  .section-header h2 { font-size: 28px; }
  .section-header p { font-size: 17px; }
  .hero h1 { font-size: 32px; }
  .hero .subtitle { font-size: 18px; }
  .product-grid { grid-template-columns: 1fr; padding: 0 16px 40px; }
  .grid-tile { min-height: 360px; padding: 32px 24px; }
  .product-card { width: 260px; }
  .compact-card { width: 200px; }
  .savings-card { width: 240px; }
  .brand-collab { padding: 40px 24px; margin: 0 16px; }
  .brand-collab h2 { font-size: 28px; }
  .page-section { padding: 48px 0; }
  .carousel-btn { width: 34px; height: 34px; }
  .carousel-btn.prev { left: 4px; }
  .carousel-btn.next { right: 4px; }
  .icon-bar { gap: 20px; }
}

